import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = (1 << 19) | 5;
    static int total_numbers, exponent, modulus, max_bit;
    static int[] count = new int[MAX_SIZE], f_array = new int[MAX_SIZE];
    static int[][] tmp1_arr = new int[20][MAX_SIZE], tmp2_arr = new int[20][MAX_SIZE], tmp3_arr = new int[20][MAX_SIZE];
    static long power_product;
    static long[][] t_arr = new long[20][MAX_SIZE];
    static long[] factorial = new long[MAX_SIZE], inv_factorial = new long[MAX_SIZE];

    static long fastExponentiation(long base, int exp) {
        long result = 1, current = base;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * current) % modulus;
            current = (current * current) % modulus;
            exp >>= 1;
        }
        return result;
    }

    static void initialize() {
        factorial[0] = 1;
        for (int i = 1; i <= max_bit; i++)
            factorial[i] = (factorial[i - 1] * i) % modulus;
        inv_factorial[max_bit] = fastExponentiation(factorial[max_bit], modulus - 2);
        for (int i = max_bit - 1; i >= 0; i--)
            inv_factorial[i] = (inv_factorial[i + 1] * (i + 1)) % modulus;
    }

    static int get_lower_power(int x) {
        int power = 1;
        while (power < x) power <<= 1;
        return power;
    }

    static void transformFWT(int[] array, int length, boolean inverse) {
        long[] temp = new long[length];
        for (int i = 0; i < length; i++) temp[i] = array[i];
        if (inverse)
            for (int i = 1; i < length; i <<= 1)
                for (int j = 0; j < length; j += (i << 1))
                    for (int k = j; k < i + j; k++)
                        temp[i + k] -= temp[k];
        else
            for (int i = 1; i < length; i <<= 1)
                for (int j = 0; j < length; j += (i << 1))
                    for (int k = j; k < i + j; k++)
                        temp[i + k] += temp[k];
        for (int i = 0; i < length; i++) {
            array[i] = (int)(temp[i] % modulus);
            if (array[i] < 0) array[i] += modulus;
        }
    }

    static void adjust_mod(long[] x) {
        for (int i = 0; i < x.length; i++) {
            if (x[i] >= power_product) x[i] -= power_product;
        }
    }

    static void multiply() {
        for (int j = 0; j <= 19; j++) {
            for (int i = 0; i <= max_bit; i++) {
                tmp1_arr[j][i] = 0;
                t_arr[j][i] = 0;
            }
        }
        for (int j = 0; j <= max_bit; j++)
            tmp1_arr[count[j]][j] = f_array[j];
        for (int j = 0; j <= 19; j++)
            transformFWT(tmp1_arr[j], max_bit + 1, false);
        for (int q = 0; q <= 19; q++)
            for (int l = 0; q + l <= 19; l++)
                for (int s = 0; s <= max_bit; s++)
                    adjust_mod(t_arr[q + l], s, (long)tmp1_arr[q][s] * tmp2_arr[l][s]);
        for (int q = 0; q <= 19; q++)
            for (int s = 0; s <= max_bit; s++)
                tmp3_arr[q][s] = (int)(t_arr[q][s] % modulus);
        for (int j = 0; j <= 19; j++)
            transformFWT(tmp3_arr[j], max_bit + 1, true);
        for (int j = 0; j <= max_bit; j++)
            f_array[j] = tmp3_arr[count[j]][j];
    }

    static void multiplySecond() {
        long[][] tmp = new long[20][MAX_SIZE];
        for (int i = 0; i <= 19; i++)
            for (int s = 0; s <= max_bit; s++)
                t_arr[i][s] = 0;
        for (int q = 0; q <= 19; q++)
            for (int l = 0; q + l <= 19; l++)
                for (int s = 0; s <= max_bit; s++)
                    adjust_mod(t_arr[q + l], s, (long)tmp2_arr[q][s] * tmp2_arr[l][s]);
        for (int q = 0; q <= 19; q++)
            for (int s = 0; s <= max_bit; s++)
                tmp[q][s] = t_arr[q][s] % modulus;
        for (int i = 0; i <= 19; i++)
            transformFWT(tmp[i], max_bit + 1, true);
        for (int i = 0; i <= 19; i++)
            for (int s = 0; s <= max_bit; s++)
                tmp2_arr[i][s] = 0;
        for (int i = 0; i <= max_bit; i++)
            tmp2_arr[count[i]][i] = (int)(tmp[count[i]][i]);
        for (int i = 0; i <= 19; i++)
            transformFWT(tmp2_arr[i], max_bit + 1, false);
    }

    static void adjust_mod(long[] arr, int index, long value) {
        arr[index] += value;
        if (arr[index] >= power_product) arr[index] -= power_product;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        total_numbers = sc.nextInt();
        exponent = sc.nextInt();
        modulus = sc.nextInt();
        power_product = (long) modulus * modulus;
        if ((total_numbers & 1) == 1) {
            System.out.println(fastExponentiation(exponent, total_numbers));
            sc.close();
            return;
        }
        f_array[0] = 1;
        max_bit = get_lower_power(total_numbers + 1) - 1;
        initialize();
        for (int i = 0; i <= max_bit; i++)
            count[i] = Integer.bitCount(i);
        for (int i = 0; i <= max_bit; i++)
            tmp2_arr[count[i]][i] = (int)inv_factorial[i];
        for (int i = 0; i <= 19; i++)
            transformFWT(tmp2_arr[i], max_bit + 1, false);
        int res_exponent = exponent;
        while (exponent > 0) {
            if ((exponent & 1) == 1) multiply();
            exponent >>= 1;
            if (exponent > 0) multiplySecond();
        }
        long result = (fastExponentiation(res_exponent, total_numbers) - factorial[total_numbers] * f_array[total_numbers] % modulus + modulus) % modulus;
        System.out.println(result);
        sc.close();
    }
}
